#!/usr/bin/env python3
"""Merge report_part1.pdf and report_part2.pdf into combined_report.pdf.

Falls back across available CLI tools: qpdf, pdftk, ghostscript.
Verifies the result page count with qpdf/pdfinfo when possible.
"""
import os
import shutil
import subprocess
import sys

INPUT_FILES = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT_FILE = "combined_report.pdf"

def run(cmd):
    print("Running:", " ".join(cmd))
    result = subprocess.run(cmd, capture_output=True, text=True)
    if result.returncode != 0:
        print("STDOUT:", result.stdout)
        print("STDERR:", result.stderr)
        raise RuntimeError(f"Command failed: {' '.join(cmd)}")
    if result.stdout.strip():
        print(result.stdout.strip())
    return result

def page_count_qpdf():
    result = run(["qpdf", "--show-npages", OUTPUT_FILE])
    return int(result.stdout.strip())

def page_count_pdfinfo():
    result = run(["pdfinfo", OUTPUT_FILE])
    for line in result.stdout.splitlines():
        if line.startswith("Pages:"):
            return int(line.split()[1])
    raise RuntimeError("pdfinfo output had no Pages line")

def main():
    for f in INPUT_FILES:
        if not os.path.exists(f):
            print(f"ERROR: input file not found: {f}", file=sys.stderr)
            sys.exit(1)

    merged = False

    if shutil.which("qpdf"):
        run(["qpdf", "--empty", "--pages"] + INPUT_FILES + ["--", OUTPUT_FILE])
        merged = True
    elif shutil.which("pdftk"):
        run(["pdftk"] + INPUT_FILES + ["cat", "output", OUTPUT_FILE])
        merged = True
    elif shutil.which("gs"):
        run(["gs", "-dBATCH", "-dNOPAUSE", "-sDEVICE=pdfwrite",
             f"-sOutputFile={OUTPUT_FILE}"] + INPUT_FILES)
        merged = True

    if not merged:
        print("ERROR: No merging tool available (tried qpdf, pdftk, gs).", file=sys.stderr)
        sys.exit(1)

    if not os.path.exists(OUTPUT_FILE):
        print(f"ERROR: {OUTPUT_FILE} was not created.", file=sys.stderr)
        sys.exit(1)

    # Verify
    if shutil.which("qpdf"):
        total = page_count_qpdf()
    elif shutil.which("pdfinfo"):
        total = page_count_pdfinfo()
    else:
        total = None

    if total is not None:
        print(f"Verification: {OUTPUT_FILE} contains {total} page(s)")
        assert total >= 1, "Page count looks wrong after merge!"
    print(f"Success: created {OUTPUT_FILE} ({os.path.getsize(OUTPUT_FILE)} bytes)")

if __name__ == "__main__":
    main()

#!/usr/bin/env node
// Probe for installed Node PDF libraries and relevant global packages.
const { execSync } = require('child_process');

function tryResolve(name) {
  try {
    const p = require.resolve(name);
    console.log(`YES  ${name} -> ${p}`);
  } catch {
    console.log(`no   ${name}`);
  }
}

console.log('Node version:', process.version);
console.log('--- local resolution ---');
for (const name of ['pdf-lib', 'pdfjs-dist', 'pdfkit', 'hummus', 'jspdf', 'pdfmake']) {
  tryResolve(name);
}

console.log('--- global root ---');
try {
  console.log(execSync('npm root -g', { encoding: 'utf8' }).trim());
} catch (e) {
  console.log('npm root -g failed:', e.message);
}

console.log('--- globally installed packages ---');
try {
  console.log(execSync('npm ls -g --depth=0 2>&1', { encoding: 'utf8' }).trim());
} catch {
  // exit code non-zero is fine; output still printed above
}

console.log('--- search common global dirs for pdf-lib ---');
const fs = require('fs');
const path = require('path');
try {
  const globalRoot = execSync('npm root -g', { encoding: 'utf8' }).trim();
  const entries = fs.readdirSync(globalRoot);
  console.log(entries.filter((e) => /pdf/i.test(e)).join('\n') || '(none matching pdf)');
} catch (e) {
  console.log('global root listing failed:', e.message);
}

